import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"أخلاقيات التكنولوجيا وحدود الأمان","description":"","frontmatter":{},"headers":[],"relativePath":"ar/68-技术伦理与安全边界.md","filePath":"ar/68-技术伦理与安全边界.md","lastUpdated":1789183869000}'),d={name:"ar/68-技术伦理与安全边界.md"};function e(o,t,h,n,s,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="أخلاقيات-التكنولوجيا-وحدود-الأمان" tabindex="-1">أخلاقيات التكنولوجيا وحدود الأمان <a class="header-anchor" href="#أخلاقيات-التكنولوجيا-وحدود-الأمان" aria-label="Permalink to &quot;أخلاقيات التكنولوجيا وحدود الأمان&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>68</td></tr><tr><td>الوحدة</td><td>الأنظمة التكنولوجية والطاقية</td></tr><tr><td>الكلمات المفتاحية</td><td>أخلاقيات التكنولوجيا، حدود الأمان، تصنيف المخاطر بالمستويات، التقنيات المحظورة، المراجعة الأخلاقية</td></tr></tbody></table><h2 id="أولاً-المبادئ-الجوهرية-لأخلاقيات-التكنولوجيا" tabindex="-1">أولاً: المبادئ الجوهرية لأخلاقيات التكنولوجيا <a class="header-anchor" href="#أولاً-المبادئ-الجوهرية-لأخلاقيات-التكنولوجيا" aria-label="Permalink to &quot;أولاً: المبادئ الجوهرية لأخلاقيات التكنولوجيا&quot;">​</a></h2><p>تستند أخلاقيات التكنولوجيا في حضارة التكافل المرساة إلى القيمة الجوهرية «التطور التكافلي». وأي بحث وتطوير وتطبيق للتكنولوجيا يجب أن يجيب على سؤال محوري: هل تعزز هذه التكنولوجيا التطور التكافلي لجميع الكائنات، أم توفر وسائل جديدة للافتراس والإضرار؟ وإذا كان الجواب هو الثاني، فمهما بلغت الفعالية الفردية للتكنولوجيا، يجب تقييدها أو منعها بصرامة.</p><p>تشمل المبادئ الجوهرية لأخلاقيات التكنولوجيا ثلاثة:</p><ul><li><strong>مبدأ عدم الإضرار</strong>: يجب ألا يسبب تطبيق التكنولوجيا ضرراً غير ضروري لأي شكل من أشكال الحياة، وألا يوفر أدوات للزراعة الافتراسية.</li><li><strong>مبدأ الكسب التكافلي</strong>: يجب أن يهدف تطوير التكنولوجيا إلى رفع درجة تكافل الحضارة كلها، لا مجرد تعزيز قدرات أفراد قلائل.</li><li><strong>مبدأ الشفافية وقابلية التتبع</strong>: عمليات البحث والتطوير وسجلات التطبيق لجميع التقنيات بمستوى هندسة القوانين يجب أن تكون قابلة للتتبع، وتخضع للمراجعة الأخلاقية والرقابة العامة.</li></ul><h2 id="ثانياً-نظام-تصنيف-المخاطر-التقنية" tabindex="-1">ثانياً: نظام تصنيف المخاطر التقنية <a class="header-anchor" href="#ثانياً-نظام-تصنيف-المخاطر-التقنية" aria-label="Permalink to &quot;ثانياً: نظام تصنيف المخاطر التقنية&quot;">​</a></h2><p>أسست الحضارة التكافلية نظاماً صارماً لتصنيف المخاطر التقنية، يجري تقييم المخاطر والإدارة المصنفة لجميع التقنيات بمستوى هندسة القوانين:</p><table tabindex="0"><thead><tr><th>مستوى الخطر</th><th>الاسم</th><th>الخصائص</th><th>متطلبات الإدارة</th></tr></thead><tbody><tr><td>R0</td><td>بلا خطر</td><td>تقنيات طبقة التقنيات الواقعية، لا تمس التلاعب بالقوانين</td><td>إدارة اعتيادية، بحث وتطبيق حران</td></tr><tr><td>R1</td><td>خطر منخفض</td><td>تقنيات طبقة التمكين بالقوانين، تحسين أداء التقنيات القائمة</td><td>إدارة بالتسجيل، يجب اجتياز اختبارات الأمان الأساسية</td></tr><tr><td>R2</td><td>خطر متوسط</td><td>تقنيات طبقة هندسة القوانين، تتضمن تلاعباً محدوداً بالقوانين</td><td>إدارة بالترخيص، يجب اجتياز المراجعة الأخلاقية والتحقق في الفضاء المعزول</td></tr><tr><td>R3</td><td>خطر مرتفع</td><td>تتضمن عمليات عالية الخطورة كإعادة كتابة المكان والتدخل في الوعي والاندماج الطاقي</td><td>رقابة صارمة، بحث حصري من مؤسسات مرخصة في أفضية معزولة بمستوى S</td></tr><tr><td>R4</td><td>المستوى المحظور</td><td>تقنيات قد تسبب انهيار الأبعاد أو إبادة الوعي أو تلوث القوانين</td><td>منع تام للبحث والتطبيق، وتصنيف المعارف المرتبطة بها محظورة</td></tr></tbody></table><p>مستويات الخطر ليست ثابتة. فمع نضج التقنيات واكتمال إجراءات الأمان، قد تخفض بعض تقنيات R3 إلى مستوى R2؛ وبالعكس، إذا اكتشفت مخاطر أمان جديدة، فقد تخضع التقنيات لرقابة مشددة.</p><h2 id="ثالثاً-حدود-الأمان-الرئيسية" tabindex="-1">ثالثاً: حدود الأمان الرئيسية <a class="header-anchor" href="#ثالثاً-حدود-الأمان-الرئيسية" aria-label="Permalink to &quot;ثالثاً: حدود الأمان الرئيسية&quot;">​</a></h2><p>ترسم أخلاقيات التكنولوجيا وحدود الأمان بوضوح الخطوط الحمراء التالية التي لا يمكن تجاوزها:</p><h3 id="_3-1-حد-أمان-الطاقة" tabindex="-1">3.1 حد أمان الطاقة <a class="header-anchor" href="#_3-1-حد-أمان-الطاقة" aria-label="Permalink to &quot;3.1 حد أمان الطاقة&quot;">​</a></h3><ul><li>تُمنع تجارب إطلاق طاقة تتجاوز قدرة استيعاب البعد الرئيسي.</li><li>يُمنع تطوير تقنيات استخراج الطاقة الهادفة إلى نهب طاقة أشكال الحياة الأخرى.</li><li>يجب أن تجرى بحوث الطاقة الشاذة في الأفضية المعزولة، وأن تلتزم بدقة بعملية التعامل مع الأنواع الثلاثة.</li></ul><h3 id="_3-2-حد-أمان-المكان" tabindex="-1">3.2 حد أمان المكان <a class="header-anchor" href="#_3-2-حد-أمان-المكان" aria-label="Permalink to &quot;3.2 حد أمان المكان&quot;">​</a></h3><ul><li>تُمنع تجارب إعادة كتابة القوانين المكانية في حالة غير معزولة.</li><li>يجب أن يمر فتح القنوات عبر الأبعاد بتقييم أمان، لمنع الأضرار الدائمة لحواجز الأبعاد.</li><li>يجب أن يتبع بناء الأفضية المعزولة وإتلافها البروتوكولات القياسية، دون ترك آثار مكانية.</li></ul><h3 id="_3-3-حد-أمان-الوعي" tabindex="-1">3.3 حد أمان الوعي <a class="header-anchor" href="#_3-3-حد-أمان-الوعي" aria-label="Permalink to &quot;3.3 حد أمان الوعي&quot;">​</a></h3><ul><li>يُمنع تطوير تقنيات التلاعب بالوعي وتحريف الذاكرة دون موافقة.</li><li>يجب أن يلتزم البحث في كيانات الاستبدال المظلم بمدونة أخلاقيات الروحين وقواعد التعامل مع الفروع الأربعة.</li><li>يجب أن تُزود تقنية واجهة مجال الوعي بآلية قاطع أمني لا رجعة فيه.</li></ul><h3 id="_3-4-حد-أمان-الزمن" tabindex="-1">3.4 حد أمان الزمن <a class="header-anchor" href="#_3-4-حد-أمان-الزمن" aria-label="Permalink to &quot;3.4 حد أمان الزمن&quot;">​</a></h3><ul><li>يجب أن تلتزم عمليات الارتداد الزمني بدقة بمبدأ «الملاحظة أولاً، ثم التدخل المحدود».</li><li>تُمنع أي تجارب أو عمليات قد تسبب مفارقات زمنية.</li><li>يجب أن تخضع سجلات الارتداد الزمني لمراقبة مستمرة من آلية الوقاية من المفارقات الزمنية ومكافحتها.</li></ul><h2 id="رابعاً-آلية-المراجعة-الأخلاقية" tabindex="-1">رابعاً: آلية المراجعة الأخلاقية <a class="header-anchor" href="#رابعاً-آلية-المراجعة-الأخلاقية" aria-label="Permalink to &quot;رابعاً: آلية المراجعة الأخلاقية&quot;">​</a></h2><p>لضمان ترسيخ أخلاقيات التكنولوجيا، أسست الحضارة التكافلية آلية مراجعة أخلاقية متعددة المستويات:</p><ol><li><strong>المراجعة قبل البحث</strong>: يجب على جميع مشاريع بحث وتطوير التقنيات بمستوى R2 فأعلى تقديم طلب مراجعة أخلاقية قبل الانطلاق، تقيّم لجنة أخلاقيات التكنولوجيا المستقلة مخاطرها ومنافعها.</li><li><strong>الرقابة أثناء التجربة</strong>: يجب أن يحضر مراقب أخلاقي طوال عملية تجارب تقنيات R3؛ وتُرفع بيانات التجارب في الزمن الحقيقي إلى نظام الرقابة الأخلاقية لشبكة المرساة.</li><li><strong>التقييم قبل التطبيق</strong>: قبل انتقال التكنولوجيا الجديدة من المختبر إلى الإنتاج الضخم، يجب أن تجتاز تقييم أمان مستقلاً وتقييم أثر اجتماعي.</li><li><strong>التتبع بعد التطبيق</strong>: التقنيات المطبقة تواصل تلقي تتبع الأمان؛ وعند اكتشاف مشكلات أخلاقية جديدة، يمكن إطلاق إجراءات إعادة التقييم أو حتى الاستدعاء في أي وقت.</li><li><strong>المشاركة العامة</strong>: يجب أن تمر القرارات التقنية الكبرى بإجراءات جلسات استماع عامة، لضمان توافق اتجاه التطور التقني مع المصالح المشتركة للحضارة كلها.</li></ol><h2 id="خامساً-قائمة-التقنيات-المحظورة" tabindex="-1">خامساً: قائمة التقنيات المحظورة <a class="header-anchor" href="#خامساً-قائمة-التقنيات-المحظورة" aria-label="Permalink to &quot;خامساً: قائمة التقنيات المحظورة&quot;">​</a></h2><p>تُصنف التقنيات التالية صراحةً تقنيات محظورة بمستوى R4، ويُمنع بحثها وتطويرها منعاً تاماً:</p><ul><li>أسلحة بمستوى تدمير الأبعاد: تقنيات أسلحة قادرة على تدمير البنية المكانية لبعد كامل.</li><li>أجهزة إبادة الوعي: تقنيات قادرة على محو وعي أشكال الحياة أو استعباده بشكل جماعي.</li><li>محركات القوانين الافتراسية: تقنيات تعمل على آلية نهب أصل أشكال الحياة الأخرى بشكل منهجي.</li><li>مولّدات المفارقات الزمنية: تقنيات تخلق المفارقات الزمنية عمداً للظفر بمنافع غير مشروعة.</li><li>ناشرات تلوث القوانين: تقنيات تنشر تلوث القوانين عمداً لتدمير حضارات أخرى.</li></ul><p>تُخزن المعارف المرتبطة بالتقنيات المحظورة مشفرة في الأرشيف المحظور للمرساة الرئيسية، ولا يمكن الاطلاع عليها إلا في أزمة أمان بمستوى الحضارة، بعد إذن من أعلى سلطة في مؤسسات الحكم التكافلية.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>إن أخلاقيات التكنولوجيا وحدود الأمان هي «نظام المكابح» للنظام التكنولوجي لحضارة التكافل المرساة. فهي تضمن أن يظل تطور التكنولوجيا خادماً للهدف الجوهري للتطور التكافلي، وألا يتحول إلى أدوات افتراس جديدة. في عصر يمكن فيه التحكم بالقوانين هندسياً، تكون الحدود الأخلاقية أهم من القدرة التقنية — فبالتشبث بالحدود فقط، يمكن للتكنولوجيا أن تصبح حقاً عوناً لتقدم عشرة آلاف عرق معاً لا تهديداً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>60-技术体系总览 (نظرة عامة على النظام التكنولوجي)</li><li>19-修炼伦理与边界 (أخلاقيات الزراعة وحدودها)</li><li>88-跨位面伦理准则 (مدونة الأخلاق عبر الأبعاد)</li></ul>',31)])])}const b=a(d,[["render",e]]);export{c as __pageData,b as default};
